return-response.set-body:
@{
                var caller = (Jwt)context.Variables["caller-jwt"];
                var me = (IResponse)context.Variables["me"];
                var body = me.Body.As();
                return new JObject(
                    new JProperty("caller_oid", caller.Claims.GetValueOrDefault("oid", "")),
                    new JProperty("graph_status", me.StatusCode),
                    new JProperty("graph_id", body["id"]),
                    new JProperty("graph_upn", body["userPrincipalName"]),
                    new JProperty("graph_error", body["error"])).ToString();
            }
